Looking at this ticket, I need to implement an authorization decision function following XACML deny-override semantics with specific pattern matching rules.

Let me break down the key requirements:

1. **Validation first**: Check all request and policy fields before making any decision
2. **Principal matching**: Exact `"*"`, `"user:<subject>"`, or `"role:<role>"` only
3. **Pattern matching**: Trailing `*` is prefix match; `"*"` matches all; others are exact (mid-string `*` is literal)
4. **Deny-override**: Any matching DENY returns DENY; else any matching ALLOW returns ALLOW; else default-deny
5. **No mutations**: Leave request and policies unchanged

```json
{"code": "def authorize(request: dict, policies: list[dict]) -> str:
    """
    Decide authorization based on request and policies using XACML deny-override.

    Returns "ALLOW" or "DENY".
    """
    # Validate request
    required_request_fields = {"subject", "roles", "action", "resource"}
    for field in required_request_fields:
        if field not in request:
            raise ValueError(f"Request missing required field: {field}")

    if not isinstance(request["roles"], list):
        raise ValueError("Request 'roles' must be a list")

    # Validate policies
    for policy in policies:
        required_policy_fields = {"effect", "principal", "action", "resource"}
        for field in required_policy_fields:
            if field not in policy:
                raise ValueError(f"Policy missing required field: {field}")

        if policy["effect"] not in ("ALLOW", "DENY"):
            raise ValueError(f"Policy 'effect' must be 'ALLOW' or 'DENY', got: {policy['effect']}")

    # Extract request fields
    subject = request["subject"]
    roles = request["roles"]
    action = request["action"]
    resource = request["resource"]

    # Evaluate policies with deny-override
    has_allow = False
    has_deny = False

    for policy in policies:
        if _matches_policy(subject, roles, action, resource, policy):
            if policy["effect"] == "DENY":
                has_deny = True
            elif policy["effect"] == "ALLOW":
                has_allow = True

    # Apply deny-override rule
    if has_deny:
        return "DENY"
    elif has_allow:
        return "ALLOW"
    else:
        return "DENY"  # default-deny


def _matches_policy(subject, roles, action, resource, policy):
    """Check if a request matches a policy."""
    return (
        _principal_matches(subject, roles, policy["principal"])
        and _pattern_matches(action, policy["action"])
        and _pattern_matches(resource, policy["resource"])
    )


def _principal_matches(subject, roles, principal):
    """Check if principal matches the request subject and roles."""
    if principal == "*":
        return True
    if principal.startswith("user:"):
        return principal[5:] == subject
    if principal.startswith("role:"):
        return principal[5:] in roles
    return False


def _pattern_matches(value, pattern):
    """Check if value matches pattern with optional trailing wildcard."""
    if pattern == "*":
        return True
    if pattern.endswith("*"):
        return value.startswith(pattern[:-1])
    return value == pattern
"}
